// ---- aviso de cookies e armazenamento (só o que o site realmente usa: veja a página Cookies e Armazenamento) ----
const ckGet=()=>{try{return JSON.parse(localStorage.getItem('ll-consent')||'null')}catch(e){return null}};
function ckClose(){const e=document.getElementById('ckb');if(e)e.remove()}
function ckSave(ap){
  try{localStorage.setItem('ll-consent',JSON.stringify({v:1,ap:!!ap,ts:new Date().toISOString()}))}catch(e){}
  try{if(ap){localStorage.setItem('ll-theme',document.documentElement.dataset.theme||'light');const f=parseFloat(document.documentElement.style.getPropertyValue('--fs'));if(f)localStorage.setItem('ll-fs',f.toFixed(2))}else{localStorage.removeItem('ll-theme');localStorage.removeItem('ll-fs')}}catch(e){}
  ckClose();toast('Preferências salvas.');
}
function ckPos(){const el=document.getElementById('ckb');if(!el)return;const t=document.getElementById('tabs');const h=t&&getComputedStyle(t).display!=='none'?t.offsetHeight:0;el.style.bottom='calc('+h+'px + .7rem + env(safe-area-inset-bottom,0px))'}
function ckShow(manage){
  ckClose();const c=ckGet(),el=document.createElement('div');el.id='ckb';el.setAttribute('role','dialog');el.setAttribute('aria-label','Cookies e armazenamento');
  el.innerHTML=`<p>Usamos o armazenamento do seu navegador para manter seu login e, se você permitir, lembrar o tema e o tamanho da letra. Não usamos cookies de análise nem de publicidade. Veja a <a href="#/privacidade">Política de Privacidade</a> e a página de <a href="#/cookies">Cookies e Armazenamento</a>.</p>${manage?`<div class="ckb-m"><p><strong>Essenciais</strong> (sempre ativos): sessão de login, retorno após o login, avisos já vistos e o registro desta escolha.</p><label class="ckb-sw"><input type="checkbox" id="ckb-ap"${c&&c.ap?' checked':''}><span><strong>Preferências de aparência</strong>: lembrar tema e tamanho da letra neste aparelho.</span></label><p class="ckb-n">Para exibir o site, o navegador também carrega fontes (Google Fonts) e uma biblioteca (jsDelivr).</p></div>`:''}<div class="ckb-b">${manage?'<button type="button" class="alt sm" id="ckb-save">Salvar preferências</button><button type="button" class="alt sm" id="ckb-x">Fechar</button>':'<button type="button" class="alt sm" id="ckb-ess">Só o essencial</button><button type="button" class="alt sm" id="ckb-all">Aceitar preferências</button><button type="button" class="alt sm" id="ckb-man">Gerenciar</button>'}</div>`;
  document.body.appendChild(el);
  const $=id=>document.getElementById(id);
  if(manage){$('ckb-save').onclick=()=>ckSave($('ckb-ap').checked);$('ckb-x').onclick=ckClose}
  else{$('ckb-ess').onclick=()=>ckSave(false);$('ckb-all').onclick=()=>ckSave(true);$('ckb-man').onclick=()=>{ckShow(true);ckPos()}}
  ckPos();
}
(()=>{const s=document.createElement('style');s.textContent='#ckb{position:fixed;left:.7rem;right:.7rem;bottom:.7rem;max-width:640px;margin:0 auto;z-index:60;background:var(--soft,#FBD9E5);color:var(--soft-ink,var(--ink,#4A1F33));border:1px solid var(--acc,#C43670);border-radius:14px;padding:.8rem 1rem;box-shadow:0 10px 28px -12px rgba(0,0,0,.35);font-size:.88rem;line-height:1.45}#ckb p{margin:0 0 .6rem;font-size:inherit}#ckb a{color:inherit;text-decoration:underline}.ckb-b{display:flex;flex-wrap:wrap;gap:.5rem}.ckb-b button{flex:1 1 auto;min-height:40px}.ckb-m{margin:.2rem 0 .6rem}.ckb-sw{display:flex;gap:.6rem;align-items:flex-start;font-weight:400;margin:.4rem 0}#ckb input[type=checkbox]{width:1.2rem;height:1.2rem;min-height:0;padding:0;margin:.15rem 0 0;flex:none;accent-color:var(--acc,#C43670)}.ckb-n{font-size:.8rem;opacity:.85}';document.head.appendChild(s)})();
