// ---- importação de capítulos a partir dos arquivos HTML da autora (roda no navegador do admin, sob RLS) ----
const NUMW={um:1,dois:2,tres:3,quatro:4,cinco:5,seis:6,sete:7,oito:8,nove:9,dez:10,onze:11,doze:12,treze:13,quatorze:14,catorze:14,quinze:15,dezesseis:16,dezessete:17,dezoito:18,dezenove:19,vinte:20,trinta:30,quarenta:40,cinquenta:50,sessenta:60,setenta:70,oitenta:80,noventa:90};
const numPT=t=>{const w=t.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/^\s*capitulo\s+/,'').split(/\s+/).filter(x=>x&&x!=='e');let n=0;for(const x of w){if(!(x in NUMW))return null;n+=NUMW[x]}return n||null};
const readFile=f=>f.text?f.text():new Promise(r=>{const fr=new FileReader();fr.onload=()=>r(fr.result);fr.readAsText(f)});
function inl(n,top=true){let o='';for(const c of n.childNodes){
  if(c.nodeType===3)o+=c.textContent.replace(/\s+/g,' ');
  else if(c.nodeType===1){const t=c.tagName,i=inl(c,false),w=k=>{const m=i.match(/^(\s*)([\s\S]*?)(\s*)$/);return m[2]?m[1]+k+m[2]+k+m[3]:i};
    if(t==='BR')o+='\n';else if(t==='STRONG'||t==='B')o+=w('**');else if(t==='EM'||t==='I'||c.classList.contains('ember'))o+=w('_');else if(c.classList.contains('whisper'))o+=w('~');else o+=i}}
  return top?o.replace(/ *\n */g,'\n').trim():o}
function parseBook(html){
  const d=new DOMParser().parseFromString(html,'text/html'),m=d.querySelector('main'),chapters=[],warn=[];let cur=null,sinopse=null;
  if(!m)return {chapters,sinopse,warn:['arquivo sem <main>']};
  for(const el of m.children){
    if(el.matches('section.sinopse')){sinopse=[...el.querySelectorAll('p')].map(p=>p.textContent.replace(/\s+/g,' ').trim()).filter(Boolean).join('\n\n');continue}
    if(el.matches('h2.chapter-title')){const sm=el.querySelector('small');const lab=sm?sm.textContent:'',ep=/^\s*ep[ií]logo\s*$/i.test(lab),tt=[...el.childNodes].filter(x=>x!==sm).map(x=>x.textContent).join('').replace(/\s+/g,' ').trim();cur={n:ep?'EP':numPT(lab),title:ep?'Epílogo: '+tt:tt,paras:[]};chapters.push(cur);continue}
    if(!cur)continue;
    if(el.matches('div.pov-badge'))cur.paras.push('@pov '+el.textContent.replace(/^\s*ponto de vista\s*[—-]\s*/i,'').trim());
    else if(el.matches('p')){const t=inl(el);if(t)cur.paras.push(t)}
    else if(el.matches('div.rupture')){for(const p of el.querySelectorAll('p')){const t=inl(p);if(t)cur.paras.push('> '+t)}}
    else warn.push('elemento ignorado: '+el.tagName)}
  return {chapters:chapters.map(c=>({n:c.n,title:c.title,body:c.paras.join('\n\n')})),sinopse,warn};
}
let IMP=null;
async function adminImportar(){
  if(!await guard())return;IMP=null;
  const {data:bk,error}=await sb.from('books').select('id,title,slug').order('sort_order');if(error)throw error;
  app.innerHTML=`<h1>Importar capítulos</h1><div class="box wide"><p class="mute">Escolha o livro e os arquivos HTML. Nada é enviado antes de você conferir o resumo e clicar em Importar.</p>
  <label>Livro<select id="imp-book">${bk.map(b=>`<option value="${b.id}" ${b.slug==='depois-de-nos'?'selected':''}>${esc(b.title)}</option>`).join('')}</select></label>
  <label>Arquivos HTML<input id="imp-files" type="file" accept=".html,text/html" multiple></label><div id="imp-sum"></div></div>`;
  document.getElementById('imp-files').onchange=async e=>{
    const all=[],warn=[],per=[];let sin=null;
    for(const f of e.target.files){const r=parseBook(await readFile(f));per.push(`${esc(f.name)}: ${r.chapters.length} capítulos`);all.push(...r.chapters);warn.push(...r.warn);if(r.sinopse)sin=r.sinopse}
    const mx=Math.max(0,...all.filter(c=>typeof c.n==='number').map(c=>c.n));all.filter(c=>c.n==='EP').forEach((c,i)=>{c.n=mx+1+i});
    const prob=[],seen=new Set();
    for(const c of all){if(!c.n)prob.push(`Número não reconhecido em "${esc(c.title)}".`);else if(seen.has(c.n))prob.push(`Capítulo ${c.n} repetido.`);else seen.add(c.n);if(!c.body)prob.push(`Capítulo ${c.n||'?'} sem texto.`)}
    all.sort((a,b)=>a.n-b.n);const ns=all.map(c=>c.n).filter(Boolean);
    for(let i=ns[0];i<=ns[ns.length-1];i++)if(!seen.has(i))prob.push(`Falta o capítulo ${i}.`);
    IMP={chapters:all,sinopse:sin,problems:prob};
    document.getElementById('imp-sum').innerHTML=`<p><strong>${all.length} capítulos</strong> (${ns[0]||'?'} a ${ns[ns.length-1]||'?'}), ${all.reduce((a,c)=>a+c.body.length,0).toLocaleString('pt-BR')} caracteres.<br><span class="mute">${per.join(' · ')}</span></p>
    ${prob.length?`<p class="state bad">${prob.join('<br>')}</p>`:''}${warn.length?`<p class="mute">Avisos: ${esc([...new Set(warn)].join(', '))}</p>`:''}
    <div class="imp">${all.map(c=>`${c.n}. ${esc(c.title)}`).join('<br>')}</div>
    <label><span><input id="imp-pub" type="checkbox" checked style="width:auto"> Publicar os capítulos</span></label>
    <label><span><input id="imp-free" type="checkbox" checked style="width:auto"> Capítulo 1 como prévia gratuita</span></label>
    <label><span><input id="imp-syn" type="checkbox" ${sin?'checked':'disabled'} style="width:auto"> Usar a sinopse do arquivo como descrição${sin?'':' (não encontrada)'}</span></label>
    <button data-a="doimport" ${prob.length||!all.length?'disabled':''}>Importar</button><p id="imp-status" class="mute" role="status"></p>`;
  };
}
